#include "PluginEditor.h"
static const juce::Colour gold{0xffd4af37},blue{0xff123c80};
AjerryVST3AudioProcessorEditor::AjerryVST3AudioProcessorEditor(AjerryVST3AudioProcessor& p):AudioProcessorEditor(&p),proc(p){
 setSize(900,520);title.setText("AJERRY CHANNEL STRIP - Compact",juce::dontSendNotification);title.setColour(juce::Label::textColourId,gold);title.setFont(juce::Font(22.0f,juce::Font::bold));title.setJustificationType(juce::Justification::centred);addAndMakeVisible(title);
 const char* names[]={"1 GATE","2 SPOTON","3 EQ","4 COMP","5 SOFTEN","6 DOUBLER","7 DELAY","8 REVERB"};
 for(int i=0;i<8;++i){tabs[i].setButtonText(names[i]);tabs[i].onClick=[this,i]{changeTab(i);};addAndMakeVisible(tabs[i]);}
 for(int i=0;i<3;++i){knobs[i].setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);knobs[i].setTextBoxStyle(juce::Slider::TextBoxBelow,false,70,20);knobs[i].setColour(juce::Slider::rotarySliderFillColourId,gold);knobs[i].setColour(juce::Slider::thumbColourId,gold);addAndMakeVisible(knobs[i]);labels[i].setColour(juce::Label::textColourId,gold);labels[i].setJustificationType(juce::Justification::centred);addAndMakeVisible(labels[i]);vals[i].setColour(juce::Label::textColourId,juce::Colours::white);vals[i].setJustificationType(juce::Justification::centred);addAndMakeVisible(vals[i]);}
 footer.setColour(juce::Label::textColourId,gold);footer.setJustificationType(juce::Justification::centred);addAndMakeVisible(footer);
 listenButton.setButtonText("LISTEN"); listenButton.setColour(juce::TextButton::buttonColourId,juce::Colours::black); listenButton.setColour(juce::TextButton::textColourOffId,gold); listenButton.onClick=[this]{bool next=!proc.spotOnListening.load(); if(next)proc.spotOnResetRequested.store(true); proc.spotOnListening.store(next); listenButton.setButtonText(next?"LISTENING...":"LISTEN"); footer.setText(next?"SPOTON is analysing the incoming beat or vocal...":"SPOTON listening paused",juce::dontSendNotification);}; addAndMakeVisible(listenButton);
 suggestButton.setButtonText("SUGGEST"); suggestButton.setColour(juce::TextButton::buttonColourId,juce::Colours::black); suggestButton.setColour(juce::TextButton::textColourOffId,gold); suggestButton.onClick=[this]{int key=proc.spotOnSuggestedKey.load(); if(key>=0){auto* param=proc.parameters.getParameter("key"); if(param)param->setValueNotifyingHost(param->convertTo0to1((float)key)); bool minor=proc.spotOnSuggestedMinor.load(); if(auto* mode=proc.parameters.getParameter("minor"))mode->setValueNotifyingHost(mode->convertTo0to1(minor?1.0f:0.0f)); const char* names[]={"C","C#","D","D#","E","F","F#","G","G#","A","A#","B"}; footer.setText("SPOTON beat/vocal key: "+juce::String(names[key])+(minor?" Minor":" Major")+" | match score "+juce::String((int)std::round(proc.spotOnConfidence.load()*100.0f))+"%",juce::dontSendNotification);}else footer.setText("SPOTON: listen to a clear vocal phrase for key suggestions",juce::dontSendNotification);}; addAndMakeVisible(suggestButton);
 changeTab(0);}
void AjerryVST3AudioProcessorEditor::changeTab(int p){page=p;for(int i=0;i<8;++i){tabs[i].setColour(juce::TextButton::buttonColourId,juce::Colours::black);tabs[i].setColour(juce::TextButton::textColourOffId,gold);tabs[i].setColour(juce::TextButton::buttonOnColourId,gold);tabs[i].setColour(juce::TextButton::textColourOnId,juce::Colours::black);tabs[i].setToggleState(i==p,juce::dontSendNotification);}
 juce::String a[3],f;const char* ids[3]={"","",""};float mins[3]={0,0,0},maxs[3]={100,100,100};
 switch(p){case 0:a[0]="THRESHOLD";a[1]="RANGE";a[2]="GATE";ids[0]="gate";mins[0]=-60;maxs[0]=0;f="Step 1 of 8 - Attack Hold Release AUTO - Always ON";break;
 case 1:a[0]="AMOUNT";a[1]="SPEED";a[2]="KEY";ids[0]="tune";ids[1]="speed";ids[2]="key";mins[1]=1;maxs[1]=100;mins[2]=0;maxs[2]=11;f="SPOTON - Live beat/vocal key analysis | major/minor pitch targeting";break;
 case 2:a[0]="HIGH-PASS";a[1]="LOW-PASS";a[2]="EQ LEARNING";ids[0]="hp";ids[1]="lp";mins[0]=20;maxs[0]=500;mins[1]=2000;maxs[1]=20000;f="EQ: HP/LP connected; learning/suggestion engine pending";break;
 case 3:a[0]="THRESHOLD";a[1]="RATIO";a[2]="GAIN";ids[0]="threshold";ids[1]="ratio";ids[2]="gain";mins[0]=-60;maxs[0]=0;mins[1]=1;maxs[1]=20;mins[2]=-12;maxs[2]=12;f="COMPRESSOR - threshold / ratio / output gain";break;
 case 4:a[0]="MODE";a[1]="AMOUNT";a[2]="ANALYSIS";ids[1]="soften";f="Soften processing connected - analysis meter pending";break;
 case 5:a[0]="MODE";a[1]="AMOUNT";a[2]="ANALYSIS";ids[1]="doubler";f="Stereo doubling connected - analysis meter pending";break;
 case 6:a[0]="TIME / SPEED";a[1]="DELAY / ECHO";a[2]="FEEDBACK";ids[0]="delayTime";ids[1]="delayMix";ids[2]="delayFeedback";mins[0]=1;maxs[0]=1000;mins[1]=0;maxs[1]=100;mins[2]=0;maxs[2]=80;f="Delay time, mix and feedback connected";break;
 default:a[0]="TIME / SIZE";a[1]="REVERB / ROOM";a[2]="ANALYSIS";ids[0]="reverbTime";ids[1]="reverbMix";mins[0]=50;maxs[0]=2000;mins[1]=0;maxs[1]=100;f="Reverb size/time and wet mix connected";break;}
 for(int i=0;i<3;++i){attachments[i].reset();labels[i].setText(a[i],juce::dontSendNotification);vals[i].setText({},juce::dontSendNotification);knobs[i].setRange(mins[i],maxs[i],0.01);knobs[i].setEnabled(ids[i][0]!='\0');knobs[i].setValue(mins[i]);if(ids[i][0]!='\0')attachments[i]=std::make_unique<Attachment>(proc.parameters,ids[i],knobs[i]);}
 footer.setText(f,juce::dontSendNotification); listenButton.setVisible(p==1); suggestButton.setVisible(p==1); repaint();}
void AjerryVST3AudioProcessorEditor::paint(juce::Graphics& g){g.fillAll(juce::Colours::black);g.setColour(gold);g.drawRect(getLocalBounds(),2);auto area=getLocalBounds().reduced(18);area.removeFromTop(100);int w=area.getWidth()/3;for(int i=0;i<3;++i){auto box=juce::Rectangle<int>(area.getX()+i*w,area.getY(),w-10,area.getHeight()-50);g.setColour(juce::Colour(0xff242424));g.fillRoundedRectangle(box.toFloat(),8);g.setColour(gold);g.drawRoundedRectangle(box.toFloat(),8,1.5f);g.setColour(blue);g.fillRoundedRectangle(box.reduced(10).toFloat(),6);}}
void AjerryVST3AudioProcessorEditor::resized(){auto r=getLocalBounds().reduced(18);title.setBounds(r.removeFromTop(38));r.removeFromTop(5);int tw=r.getWidth()/8;for(int i=0;i<8;++i)tabs[i].setBounds(r.getX()+i*tw,r.getY(),tw-2,36);r.removeFromTop(18);int cw=r.getWidth()/3;for(int i=0;i<3;++i){auto b=juce::Rectangle<int>(r.getX()+i*cw,r.getY(),cw-10,r.getHeight()-40);labels[i].setBounds(b.removeFromTop(32));knobs[i].setBounds(b.removeFromTop(150).reduced(28,10));vals[i].setBounds(b.removeFromTop(28));}listenButton.setBounds(18,getHeight()-35,92,26); suggestButton.setBounds(116,getHeight()-35,92,26); footer.setBounds(215,getHeight()-35,getWidth()-235,28);}
